import{_ as r,C as s,o,c as d,a2 as e,b as p,w as n,a as l,E as i,a3 as u}from"./chunks/framework.BC3NdntU.js";const _=JSON.parse('{"title":"11.8 底层逻辑打通:统一框架","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.8-底层逻辑打通统一框架.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.8-底层逻辑打通统一框架.md","lastUpdated":1789010886000}'),h={name:"卷十一-AIAgentHarness与提示词工程/11.8-底层逻辑打通统一框架.md"};function g(q,t,c,b,A,E){const a=s("Mermaid");return o(),d("div",null,[t[1]||(t[1]=e('<h1 id="_11-8-底层逻辑打通-统一框架" tabindex="-1">11.8 底层逻辑打通:统一框架 <a class="header-anchor" href="#_11-8-底层逻辑打通-统一框架" aria-label="Permalink to &quot;11.8 底层逻辑打通:统一框架&quot;">​</a></h1><h2 id="引言-七章之后-把它们焊成-一个模型" tabindex="-1">引言:七章之后,把它们焊成&quot;一个模型&quot; <a class="header-anchor" href="#引言-七章之后-把它们焊成-一个模型" aria-label="Permalink to &quot;引言:七章之后,把它们焊成&quot;一个模型&quot;&quot;">​</a></h2><p>前面七章讲了引擎、循环、运行时、上下文、工具、提示词。这一章把它们<strong>收束成一个统一框架</strong>,离开时脑子里只有一张图和一个概括。</p><hr><h2 id="一、一张总图-四要素-一个循环" tabindex="-1">一、一张总图:四要素 + 一个循环 <a class="header-anchor" href="#一、一张总图-四要素-一个循环" aria-label="Permalink to &quot;一、一张总图:四要素 + 一个循环&quot;">​</a></h2>',5)),(o(),p(u,null,{default:n(()=>[i(a,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20H%5BHarness%20%E8%BF%90%E8%A1%8C%E6%97%B6%3Cbr%2F%3E%E7%8A%B6%E6%80%81%E6%9C%BA%2B%E5%AE%B9%E9%94%99%2B%E8%A7%82%E6%B5%8B%5D%20--%3E%20P%5BPrompt%20%E6%84%8F%E5%9B%BE%2F%E7%BA%A6%E6%9D%9F%3Cbr%2F%3E%E6%96%B9%E5%90%91%E7%9B%98%5D%0A%20%20%20%20H%20--%3E%20C%5BContext%20%E7%8A%B6%E6%80%81%2F%E8%AE%B0%E5%BF%86%3Cbr%2F%3E%E8%AE%B0%E5%BF%86%5D%0A%20%20%20%20H%20--%3E%20T%5BTools%20%E8%83%BD%E5%8A%9B%3Cbr%2F%3E%E6%89%8B%E8%84%9A%5D%0A%20%20%20%20P%20%26%20C%20%26%20T%20--%3E%20L%5BLLM%20%E5%BC%95%E6%93%8E%3Cbr%2F%3Enext-token%20%E9%A2%84%E6%B5%8B%5D%0A%20%20%20%20L%20--%3E%20A%5B%E5%86%B3%E7%AD%96%3A%E6%80%9D%E8%80%83%2B%E8%A1%8C%E5%8A%A8%5D%0A%20%20%20%20A%20--%3E%7C%E8%B0%83%E5%B7%A5%E5%85%B7%7C%20T%0A%20%20%20%20T%20--%3E%20O%5B%E8%A7%82%E5%AF%9F%20Observation%5D%0A%20%20%20%20O%20--%3E%20C%0A%20%20%20%20O%20--%3E%20A%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e(`<table tabindex="0"><thead><tr><th>要素</th><th>比喻</th><th>负责</th><th>章节</th></tr></thead><tbody><tr><td>LLM</td><td>发动机</td><td>next-token 算力与智能</td><td>11.1</td></tr><tr><td>Prompt</td><td>方向盘</td><td>意图/约束/格式</td><td>11.6/11.7</td></tr><tr><td>Tools</td><td>手脚</td><td>碰外部世界</td><td>11.5</td></tr><tr><td>Context</td><td>记忆</td><td>状态/历史/知识</td><td>11.4</td></tr><tr><td>Harness</td><td>车身+车手</td><td>串成容错循环</td><td>11.2/11.3</td></tr></tbody></table><hr><h2 id="二、总结" tabindex="-1">二、总结 <a class="header-anchor" href="#二、总结" aria-label="Permalink to &quot;二、总结&quot;">​</a></h2><blockquote><p><strong>Agent = 一个&quot;有记忆、有手脚、有方向&quot;的 next-token 预测器,被一个容错的循环(Harness)驱动着反复&quot;思考→行动→观察&quot;,直到达成目标。</strong></p></blockquote><p>三个判断:① 本质(只会预测 next token);② 放大(工具/上下文/提示词);③ 收敛(Harness 循环+容错变成可靠系统)。</p><hr><h2 id="三、openai-的视角-人类掌舵-智能体执行" tabindex="-1">三、OpenAI 的视角:&quot;人类掌舵,智能体执行&quot; <a class="header-anchor" href="#三、openai-的视角-人类掌舵-智能体执行" aria-label="Permalink to &quot;三、OpenAI 的视角:&quot;人类掌舵,智能体执行&quot;&quot;">​</a></h2><blockquote><p><strong>&quot;人类掌舵,智能体执行。&quot;(Humans steer, agents execute.)</strong></p></blockquote><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程主要工作,从&quot;写代码&quot;→ 变成&quot;设计环境、明确意图、构建反馈回路&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>博客关键词</th><th>本卷对应</th></tr></thead><tbody><tr><td>设计环境</td><td>11.3 Harness + 11.4 上下文</td></tr><tr><td>明确意图</td><td>11.6/11.7 提示词</td></tr><tr><td>构建反馈回路</td><td>11.2 循环 + 11.5 工具</td></tr></tbody></table><p><strong>最硬的一句(收束点):</strong></p><blockquote><p><strong>&quot;构建软件仍然需要纪律,但纪律更多地体现在支撑结构上,而不是代码上。&quot;</strong></p></blockquote><p>反过来读 = 本卷全部:<strong>Agent 工程的竞争力,不在模型,而在你为它搭建的&quot;支撑结构&quot;(Harness、上下文、工具、提示词)。</strong></p><hr><h2 id="四、从-会用-到-会设计-三层" tabindex="-1">四、从&quot;会用&quot;到&quot;会设计&quot;三层 <a class="header-anchor" href="#四、从-会用-到-会设计-三层" aria-label="Permalink to &quot;四、从&quot;会用&quot;到&quot;会设计&quot;三层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>你在做什么</th><th>对应</th></tr></thead><tbody><tr><td>L1 会调</td><td>写好 prompt 拿好答案</td><td>11.6/11.7</td></tr><tr><td>L2 会搭</td><td>接工具、跑循环</td><td>11.2/11.5</td></tr><tr><td>L3 会设计</td><td>设计环境/约束/反馈回路,让一群 Agent 可靠协作</td><td>11.3/11.4/11.8</td></tr></tbody></table><hr><h2 id="五、落地清单-判断-agent-系统靠不靠谱" tabindex="-1">五、落地清单:判断 Agent 系统靠不靠谱 <a class="header-anchor" href="#五、落地清单-判断-agent-系统靠不靠谱" aria-label="Permalink to &quot;五、落地清单:判断 Agent 系统靠不靠谱&quot;">​</a></h2><ol><li>循环有无兜底?2. 容错是否分层?3. 上下文是否克制?4. 工具是否设防?5. 输出是否可解析?6. 事实是否靠工具锚定?7. 人是否在关键环上?</li></ol><hr><hr><p><strong>AI 原生前端(AI 生成 UI/代码,2026):</strong></p><p>AI 从&quot;补全&quot;进化为&quot;<strong>直接生成 UI/代码</strong>&quot;:</p><ul><li><strong>v0</strong>:自然语言描述 → 直接生成 React 组件(UI 原型)</li><li><strong>Cursor</strong>:AI 原生 IDE,Composer 跨文件修改</li><li><strong>CodeBuddy</strong>:Figma 设计稿 → 代码</li><li><strong>Copilot / Claude Code / Codex</strong>:代码补全、重构、多文件编辑</li></ul><p><strong>趋势</strong>:从&quot;AI 辅助写码&quot;→&quot;<strong>AI 原生开发</strong>&quot;(设计稿 → Design Tokens → 组件 → 页面全链路);前端因组件化/可视化,对 AI 接受度最高(84% 开发者常态用 AI)。</p><blockquote><p>AI 原生前端不是&quot;替代人写码&quot;,而是&quot;<strong>把设计意图直接编译成可运行 UI</strong>&quot;,人的角色转向&quot;定义意图 + 校验结果&quot;——这正是本卷&quot;人类掌舵、智能体执行&quot;在 UI 层的落地。</p></blockquote><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>统一框架:LLM(引擎)+Prompt(方向盘)+Tools(手脚)+Context(记忆),由 Harness 串成容错循环</span></span>
<span class="line"><span>Agent=有记忆、有手脚、有方向的 next-token 预测器,被容错循环驱动直到达成目标</span></span>
<span class="line"><span>OpenAI 定调:人类掌舵,智能体执行 → 纪律在支撑结构,不在代码</span></span>
<span class="line"><span>层次:会调(prompt)&lt; 会搭(循环/工具)&lt; 会设计(环境/约束/反馈回路)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="七、终章思考题" tabindex="-1">七、终章思考题 <a class="header-anchor" href="#七、终章思考题" aria-label="Permalink to &quot;七、终章思考题&quot;">​</a></h2><p><strong>Q1:用一段话向&quot;只会用 ChatGPT 聊天&quot;的人解释什么是 Agent?</strong></p><p>模型本身只会&quot;接话&quot;(预测下一个词)。Agent 是给它装<strong>手脚(工具)、记忆(上下文)、方向盘(提示词)</strong>,再套一个<strong>循环(反复思考→行动→观察)</strong>,让它从&quot;只会聊天&quot;变成&quot;能查、能写、能执行、能自我纠错&quot;的任务机器。</p><p><strong>Q2:为什么说&quot;Agent 的竞争力在支撑结构,而非模型&quot;?</strong></p><p>模型能力是<strong>外部的、大家都一样</strong>;真正决定系统好不好用的是你<strong>为它搭建的环境</strong>:上下文怎么组织、工具怎么设防、循环怎么容错、反馈回路怎么建。模型决定上限,支撑结构决定<strong>能否稳定接近上限</strong>——这正是 harness engineering 的意义。</p><p><strong>Q3:本卷的&quot;一张图和一个概括&quot;分别是什么?</strong></p><p><strong>一张图</strong>:LLM 引擎 + Prompt 方向盘 + Tools 手脚 + Context 记忆,被 Harness 的循环(思考→行动→观察)驱动。<strong>概括</strong>:Agent 是有记忆、有手脚、有方向的 next-token 预测器,被容错循环驱动直到达成目标。</p><p><strong>Q4:四要素(prompt/context/tool/loop)各对应什么比喻?</strong></p><p>LLM=发动机、Prompt=方向盘、Tools=手脚、Context=记忆、Harness(循环)=车身+车手。前四者被 Harness 串成&quot;思考→行动→观察&quot;的循环。</p><p><strong>Q5:判断 Agent 系统靠不靠谱的 checklist(举几条)?</strong></p><p>① 循环有无兜底(步数上限/终止/死循环检测);② 容错是否分层(超时→退避→再入→降级);③ 上下文是否克制(地图而非说明书);④ 工具是否设防(最小权限/沙箱/人审);⑤ 事实是否靠工具锚定;⑥ 人是否在关键环上。</p><p><strong>Q6:&quot;会调 / 会搭 / 会设计&quot;三层分别是什么?</strong></p><p>L1 会调:写好 prompt 拿好答案;L2 会搭:给模型接工具、跑循环;L3 会设计:设计环境、约束、反馈回路,让一群 Agent 可靠协作。多数人停 L1,拉差距在 L2/L3。</p><hr><p>📎 参考:OpenAI《harness-engineering》博客、<a href="https://www.anthropic.com/" target="_blank" rel="noreferrer">Anthropic</a>《Building Effective Agents》、本卷 11.1~11.7</p>`,44))])}const B=r(h,[["render",g]]);export{_ as __pageData,B as default};
